     1|/**
     2| * IVX Autonomous Execution — the layer that turns IVX from "verification mode"
     3| * into a self-DRIVING capital business. It runs the REAL sourcing engines on a
     4| * daily cadence and writes their output into the durable CRM + outreach stores
     5| * so work accumulates without a human prompt.
     6| *
     7| * HARD HONESTY RULES (inherited from every engine this composes):
     8| *   - Discovery is REAL: candidates come from `discoverLeads`, which reads public
     9| *     U.S. SEC EDGAR Form D filings. Every record carries a verifiable SEC URL.
    10| *     Nothing is fabricated; unknown fields stay null.
    11| *   - Saving to the CRM is REAL: each promoted lead becomes a durable
    12| *     `InvestorRecord` attributed to its public SEC source (deduped by source URL
    13| *     at discovery time and by identity key at the CRM layer).
    14| *   - Outreach is DRAFTED + QUEUED, never silently "sent". Actual sending requires
    15| *     a configured email provider (none is wired in this deployment), so the
    16| *     capital-outreach engine stages messages for approval and reports
    17| *     `sendingEnabled:false` honestly instead of pretending mail went out.
    18| *   - This module is the SINGLE place the scheduler calls for buyer / investor /
    19| *     JV / outreach execution, so every run is grounded, attributable, and logged.
    20| */
    21|import {
    22|  discoverLeads,
    23|  approveLead,
    24|  type StagedLead,
    25|  type InvestorDiscoveryClass,
    26|} from './ivx-lead-discovery';
    27|import {
    28|  createOutreachMessage,
    29|  listOutreachMessages,
    30|  submitForApproval,
    31|  type OutreachType,
    32|} from './ivx-outreach-store';
    33|import { isSesConfigured } from './ivx-ses-email';
    34|import {
    35|  listInvestors,
    36|  updateInvestor,
    37|  createInvestor,
    38|  investorDedupeKey,
    39|  type InvestorRecord,
    40|  type PartyType,
    41|} from './ivx-investor-crm-store';
    42|
    43|export const IVX_AUTONOMOUS_EXECUTION_MARKER = 'ivx-autonomous-execution-2026-06-14';
    44|
    45|export type ExecutionEngine = 'buyer' | 'investor' | 'jv' | 'outreach' | 'tokenized_buyer';
    46|
    47|/** Marker written into a record's investmentType so tokenized buyers are countable + distinct. */
    48|export const TOKENIZED_BUYER_INVESTMENT_TYPE = 'Tokenized / digital-asset real estate capital';
    49|
    50|/** Result of one engine run — every count is grounded in real records. */
    51|export type EngineRunResult = {
    52|  marker: string;
    53|  engine: ExecutionEngine;
    54|  ok: boolean;
    55|  ranAt: string;
    56|  durationMs: number;
    57|  /** Real candidates pulled from public SEC filings this run. */
    58|  discovered: number;
    59|  /** Newly created durable CRM records this run. */
    60|  savedToCrm: number;
    61|  /** Candidates already in the pipeline (deduped, not re-added). */
    62|  duplicatesSkipped: number;
    63|  /** Outreach drafts created + queued for approval (outreach engine only). */
    64|  outreachQueued: number;
    65|  /** True only when an email provider is configured (never faked). */
    66|  sendingEnabled: boolean;
    67|  source: string;
    68|  /** Verifiable evidence (SEC filing URLs / CRM ids) — proof of real work. */
    69|  evidence: string[];
    70|  note: string;
    71|  error: string | null;
    72|};
    73|
    74|/** True only when a real outbound email provider is configured. Never faked. */
    75|export function isOutreachSendingEnabled(): boolean {
    76|  return Boolean(
    77|    isSesConfigured() ||
    78|      process.env.RESEND_API_KEY ||
    79|      process.env.SENDGRID_API_KEY ||
    80|      process.env.POSTMARK_API_TOKEN ||
    81|      process.env.SMTP_URL,
    82|  );
