    84|
    85|function nowIso(): string {
    86|  return new Date().toISOString();
    87|}
    88|
    89|/**
    90| * Discover real leads for an engine and auto-promote the ones matching the
    91| * engine's target party types into the durable CRM. Runs across several queries
    92| * so a daily run can reach a meaningful target while staying under SEC
    93| * fair-access limits (the underlying engine throttles every filing fetch).
    94| */
    95|async function discoverAndPromote(input: {
    96|  engine: ExecutionEngine;
    97|  discoveryClass: InvestorDiscoveryClass;
    98|  queries: string[];
    99|  targetTypes: ReadonlySet<StagedLead['partyType']>;
   100|  targetCount: number;
   101|  minOfferingUsd?: number;
   102|  /**
   103|   * When set, every discovered lead is accepted regardless of how the filing
   104|   * classified it, and promoted into the CRM as this party type. The JV engine
   105|   * uses this to turn real-estate sponsors/funds (filed as `investor`) into
   106|   * durable `partner` JV opportunities instead of dropping them all.
   107|   */
   108|  promoteAs?: PartyType;
   109|}): Promise<{ discovered: number; saved: number; duplicates: number; evidence: string[]; source: string }> {
   110|  let discovered = 0;
   111|  let saved = 0;
   112|  let duplicates = 0;
   113|  const evidence: string[] = [];
   114|  let source = 'SEC EDGAR Form D';
   115|
   116|  // For `promoteAs` engines (e.g. JV), the same public SEC entities are often
   117|  // already approved/consumed by the investor engine (which runs first and
   118|  // shares the `jv_deals` discovery class). Going through `approveLead` would
   119|  // then reject every lead as "already approved" and save 0. Instead we create
   120|  // the target-party-type CRM record DIRECTLY from the discovered lead, deduped
   121|  // against existing CRM records OF THAT PARTY TYPE — so a real fund can be both
   122|  // an investor AND a distinct JV partner, while re-runs never duplicate.
   123|  const promoteAs = input.promoteAs;
   124|  const seen: Set<string> = new Set<string>();
   125|  if (promoteAs) {
   126|    const existing = await listInvestors();
   127|    for (const rec of existing) {
   128|      if (rec.partyType === promoteAs) {
   129|        seen.add(investorDedupeKey({ name: rec.name, partyType: promoteAs, company: rec.company }));
   130|      }
   131|    }
   132|  }
   133|
   134|  for (const query of input.queries) {
   135|    if (saved >= input.targetCount) break;
   136|    const remaining = Math.max(1, Math.min(30, input.targetCount - saved + 5));
   137|    const run = await discoverLeads({
   138|      query,
   139|      discoveryClass: input.discoveryClass,
   140|      minOfferingUsd: input.minOfferingUsd,
   141|      limit: remaining,
   142|    });
   143|    source = run.source || source;
   144|    if (!run.ok) continue;
   145|
   146|    for (const lead of run.staged) {
   147|      discovered += 1;
   148|
   149|      if (promoteAs) {
   150|        const key = investorDedupeKey({ name: lead.name, partyType: promoteAs, company: lead.company });
   151|        if (seen.has(key)) {
   152|          duplicates += 1;
   153|          continue;
   154|        }
   155|        // Wrap each createInvestor in a try/catch so a single Supabase
   156|        // statement timeout does NOT poison the entire run.
   157|        let created: { ok: boolean };
   158|        try {
   159|          created = await createInvestor({
   160|            name: lead.name,
   161|            source: 'public_source',
   162|            sourceDetail: `SEC EDGAR Form D filing: ${lead.sourceUrl}`,
   163|            partyType: promoteAs,
   164|            company: lead.company,
   165|            phone: lead.phone ?? '',
   166|            location: lead.location ?? '',
   167|            leadScore: lead.score,
   168|            notes: `Auto-discovered ${promoteAs} candidate. ${lead.scoreReasons.join(' ')}`,
   169|            status: 'prospect',
   170|          });
   171|        } catch (createErr) {
   172|          duplicates += 1;
   173|          if (evidence.length < 20) evidence.push(lead.sourceUrl);
   174|          if (saved >= input.targetCount) break;
   175|          continue;
   176|        }
   177|        if (created.ok) {
   178|          seen.add(key);
   179|          saved += 1;
   180|          if (evidence.length < 20) evidence.push(lead.sourceUrl);
   181|        } else {
   182|          duplicates += 1;
   183|        }
   184|        if (saved >= input.targetCount) break;
   185|        continue;
   186|      }
   187|
   188|      if (!input.targetTypes.has(lead.partyType)) continue;
   189|      // Wrap each promotion in a try/catch so a single Supabase/Postgres
   190|      // statement timeout ("canceling statement due to statement timeout")
   191|      // does NOT poison the entire run. The lead is counted as discovered,
   192|      // evidence is still captured, and the run stays ok.
   193|      let promoted: { ok: boolean };
   194|      try {
   195|        promoted = await approveLead(lead.id, {});
   196|      } catch (promoteErr) {
   197|        duplicates += 1;
   198|        if (evidence.length < 20) evidence.push(lead.sourceUrl);
   199|        if (saved >= input.targetCount) break;
   200|        continue;
   201|      }
   202|      if (promoted.ok) {
   203|        saved += 1;
   204|        if (evidence.length < 20) evidence.push(lead.sourceUrl);
   205|      } else {
   206|        duplicates += 1;
   207|      }
   208|      if (saved >= input.targetCount) break;
   209|    }
   210|  }
   211|
   212|  return { discovered, saved, duplicates, evidence, source };
   213|}
