   429|
   430|const OUTREACH_TYPE_FOR_PARTY: Partial<Record<PartyType, OutreachType>> = {
   431|  buyer: 'buyer_intro',
   432|  investor: 'investor_intro',
   433|  partner: 'investor_intro',
   434|};
   435|
   436|/**
   437| * CAPITAL OUTREACH ENGINE — build the daily outreach queue from new CRM
   438| * prospects that don't yet have a message, draft a compliant intro, and submit
   439| * it for approval. It NEVER auto-sends: real sending is gated behind a configured
   440| * email provider (reported via `sendingEnabled`). This is execution, not
   441| * simulation — the queue is durable and the owner approves before anything goes.
   442| */
   443|export async function runCapitalOutreachEngine(maxQueue: number = 25): Promise<EngineRunResult> {
   444|  const start = Date.now();
   445|  try {
   446|    const [investors, messages] = await Promise.all([listInvestors(), listOutreachMessages()]);
   447|
   448|    // Companies that already have an outreach message — never double-queue.
   449|    const contacted = new Set(
   450|      messages.map((m) => `${m.recipientCompany.toLowerCase()}|${m.recipientName.toLowerCase()}`),
   451|    );
   452|
   453|    const candidates = investors.filter(
   454|      (inv) => inv.status === 'prospect' && OUTREACH_TYPE_FOR_PARTY[inv.partyType],
   455|    );
   456|
   457|    let queued = 0;
   458|    const evidence: string[] = [];
   459|    for (const inv of candidates) {
   460|      if (queued >= maxQueue) break;
   461|      const key = `${inv.company.toLowerCase()}|${inv.name.toLowerCase()}`;
   462|      if (contacted.has(key)) continue;
   463|      const type = OUTREACH_TYPE_FOR_PARTY[inv.partyType];
   464|      if (!type) continue;
   465|      const created = await createOutreachMessage({
   466|        type,
   467|        recipientName: inv.name,
   468|        recipientCompany: inv.company,
   469|        relatedDeal: '',
   470|        contextNote: inv.notes,
   471|        senderName: 'IVX Holdings — Investor Relations',
   472|      });
   473|      if (created.ok) {
   474|        await submitForApproval(created.message.id);
   475|        contacted.add(key);
   476|        queued += 1;
   477|        if (evidence.length < 20) evidence.push(created.message.id);
   478|      }
   479|    }
   480|
   481|    const sendingEnabled = isOutreachSendingEnabled();
   482|    return {
   483|      marker: IVX_AUTONOMOUS_EXECUTION_MARKER,
   484|      engine: 'outreach',
   485|      ok: true,
   486|      ranAt: nowIso(),
   487|      durationMs: Date.now() - start,
   488|      discovered: candidates.length,
   489|      savedToCrm: 0,
   490|      duplicatesSkipped: 0,
   491|      outreachQueued: queued,
   492|      sendingEnabled,
   493|      source: 'Investor CRM prospects',
   494|      evidence,
   495|      note: sendingEnabled
   496|        ? `${queued} outreach message(s) drafted and queued for approval; an email provider is configured so approved messages can be sent.`
   497|        : `${queued} outreach message(s) drafted and queued for owner approval. Sending is NOT enabled — configure an email provider (RESEND_API_KEY / SENDGRID_API_KEY / SMTP_URL) to dispatch approved messages. No message was sent.`,
   498|      error: null,
   499|    };
   500|  } catch (error) {
   501|    return failedRun('outreach', start, error);
   502|  }
   503|}
