   546|/** Read-only roll-up of what the engines have produced (for the daily report). */
   547|export async function summarizeAutonomousExecution(): Promise<AutonomousExecutionSummary> {
   548|  const [investors, messages, ideas] = await Promise.all([
   549|    listInvestors().catch(() => [] as InvestorRecord[]),
   550|    listOutreachMessages().catch(() => []),
   551|    (async () => {
   552|      try {
   553|        const { listIdeas } = await import('./ivx-innovation-store');
   554|        return await listIdeas();
   555|      } catch {
   556|        return [];
   557|      }
   558|    })(),
   559|  ]);
   560|  const buyers = investors.filter((i) => i.partyType === 'buyer').length;
   561|  const tokenizedBuyers = investors.filter(isTokenizedBuyer).length;
   562|  const invs = investors.filter((i) => i.partyType === 'investor').length;
   563|  const partners = investors.filter((i) => i.partyType === 'partner').length;
   564|  const queued = messages.filter((m) => m.status === 'pending_approval' || m.status === 'draft').length;
   565|  const sent = messages.filter((m) => m.status === 'sent' || m.status === 'replied').length;
